public class Complex{private final double real,imaginary;public Complex(double r,double i){real=r;imaginary=i;}public double real(){return real;}public double imaginary(){return imaginary;}public Complex add(Complex b){return new Complex(real+b.real,imaginary+b.imaginary);}public Complex subtract(Complex b){return new Complex(real-b.real,imaginary-b.imaginary);}public Complex multiply(Complex b){return new Complex(real*b.real-imaginary*b.imaginary,real*b.imaginary+imaginary*b.real);}public Complex divide(Complex b){double d=b.real*b.real+b.imaginary*b.imaginary;return new Complex((real*b.real+imaginary*b.imaginary)/d,(imaginary*b.real-real*b.imaginary)/d);}public static Complex sum(Complex[]a){Complex result=new Complex(0,0);for(Complex b:a)result=result.add(b);return result;}public static Complex product(Complex[]a){Complex result=new Complex(1,0);for(Complex b:a)result=result.multiply(b);return result;}}
